/* ========== 全局变量 ========== */
:root {
  --theme-color-1: #893619 !important;
  --theme-color-2: var(--SmartThemeUnderlineColor);
  --ui-color-main: rgba(248, 245, 238, 0.92) !important;
  --ui-color-sec: rgba(238, 233, 222, 0.9) !important;
  --top-bar-color: var(--SmartThemeBorderColor);
  --top-bar-underline-color: var(--theme-color-1);
  --top-bar-icon-color: var(--text-color-main);
  --chat-background-color: var(--SmartThemeChatTintColor);
  --text-color-main: #0E2110 !important;
  --text-color-sec: #B8D87F !important;
  --user-color: var(--SmartThemeUserMesBlurTintColor);
  --char-color: var(--SmartThemeBotMesBlurTintColor);
  --code-color: rgba(238, 233, 222, 0.5) !important;
  --gradient-main: linear-gradient(
    135deg,
    var(--theme-color-1) 30%,
    color-mix(in srgb, var(--theme-color-1) 50%, var(--theme-color-2) 50%) 50%,
    var(--theme-color-2) 70%
  );
  --apple-top-icon-size: 32px;
  --apple-top-icon-gap: 8px;
}

:root {
  --mes-width: 100%;
  --mes-block-width: 98%;
  --box-border-radius: 0px;
  --top-distance: 0px;
  --bottom-distance: 0px;
  --chat-send-spacing: 0px;
  --leftRight-chat-spacing: 0px;
  --scroll-width: 5px;
  --icon-size: var(--mainFontSize);
  --border-radius-small: 5px;
  --border-radius-medium: 10px;
  --spacing-long: 10px;
  --spacing-short: 5px;
  --topBarIconSize: calc(var(--icon-size) * 2);
}

/* ========== 标题 ========== */
.standoutHeader strong,
#right-nav-panel h2,
.drawer-content > h3,
.drawer-content .flex-container h3:first-of-type:not(#Backgrounds .textAlignCenter),
.drawer-content .flex-container .flex-container h3:first-of-type,
.popup h3:not(dialog *) {
  font-size: calc(var(--mainFontSize) * 1.2);
  font-weight: 600;
  color: var(--text-color-main);
  letter-spacing: 0.1em;
  white-space: nowrap;
  line-height: 2;
}

.standoutHeader strong::before,
#right-nav-panel h2::before,
.drawer-content > h3::before,
.drawer-content .flex-container h3:first-of-type:not(#Backgrounds .textAlignCenter)::before,
.drawer-content .flex-container .flex-container h3:first-of-type::before,
.popup h3:not(dialog *)::before {
  content: "୨ৎ";
  position: relative;
  color: #893619;
  font-size: calc(var(--mainFontSize) * 1.15);
  margin-right: 4px;
  text-shadow: none;
  letter-spacing: -0.05em;
}

@supports (-webkit-touch-callout: none) {
  .standoutHeader strong::before,
  #right-nav-panel h2::before,
  .drawer-content > h3::before,
  .drawer-content .flex-container h3:first-of-type:not(#Backgrounds .textAlignCenter)::before,
  .drawer-content .flex-container .flex-container h3:first-of-type::before,
  .popup h3:not(dialog *)::before {
    font-size: calc(var(--mainFontSize) * 1.4);
  }
}

.standoutHeader:not(h4),
#rm_PinAndTabs,
#top-settings-holder .drawer:not(:first-child):not(:last-child) .drawer-content .alignItemsBaseline.wide100p,
#rm_api_block .flex-container.alignItemsBaseline,
#title_api,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
#WorldInfo .alignitemscenter:not(#world_popup *),
#user-settings-block div[name="userSettingsRowOne"],
#rm_extensions_block .alignitemscenter.flex-container.wide100p:not(.justifyCenter) {
  background-image: none;
  border-radius: 0;
  border: none;
  border-bottom: 1px solid var(--ui-color-sec);
  margin-bottom: calc(var(--mainFontSize) * 0.4);
  padding-bottom: calc(var(--mainFontSize) * 0.2);
}

.drawer-content .alignItemsBaseline { align-items: center !important; }
#title_api { padding-bottom: 0; }

#title_api::before,
#Backgrounds h3.margin0.flex2::before,
#rm_extensions_block .margin0.flex1::before,
#rm_button_selected_ch h2::before {
  margin-right: calc(var(--mainFontSize) * 0.4);
}

/* ========== 抽屉 ========== */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder *) {
  border-width: 0 0 0 3px !important;
  border-color: transparent !important;
  border-style: solid;
  border-radius: 0;
  background-image: none !important;
  padding-left: 7px;
  border-image: linear-gradient(
      to bottom,
      transparent 25%,
      var(--theme-color-1) 25%,
      var(--theme-color-1) 75%,
      transparent 75%
    ) 1 100%;
}

.inline-drawer-icon { font-size: var(--icon-size); }

/* ========== 滚动条 ========== */
::-webkit-scrollbar { width: var(--scroll-width); }
::-webkit-scrollbar:horizontal { height: var(--scroll-width); }
::-webkit-scrollbar-track { background: transparent; }

::-webkit-scrollbar-thumb:vertical,
::-webkit-scrollbar-thumb:horizontal {
  background-color: rgba(137, 54, 25, 0.3) !important;
  box-shadow: none;
  border: 0;
}

::-webkit-scrollbar-thumb:vertical:hover,
::-webkit-scrollbar-thumb:horizontal:hover {
  background-color: rgba(137, 54, 25, 0.6) !important;
}

/* ========== 输入框（菜单内） ========== */
input[type="text"]:not(#send_form textarea),
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not(#send_form textarea):not([type="search"]) {
  background-color: var(--ui-color-sec) !important;
  color: #0E2110 !important;
  border: 1px solid rgba(14, 33, 16, 0.2) !important;
}

input[type="text"]:focus,
input[type="number"]:focus,
input[type="switch"]:focus,
input:not([type]):focus,
textarea:not(#send_form textarea):not([type="search"]):focus {
  border: 1px solid #893619 !important;
  box-shadow: 0 0 5px rgba(137, 54, 25, 0.15) !important;
  outline: none !important;
}

textarea[type="search"] {
  background-color: transparent !important;
  border: none !important;
}

.range-block { margin: calc(var(--mainFontSize) * 0.6) 0; }
.range-block-counter { margin-left: 20px; }

.text_pole:not(.objective-task) {
  background-color: var(--ui-color-sec);
  border: none;
}

/* ========== 按钮 ========== */
.menu_button:not(.mes_edit_buttons *),
.menu_button_icon {
  background-color: var(--ui-color-sec) !important;
  border: 1px solid rgba(137, 54, 25, 0.2) !important;
  color: #0E2110 !important;
  transition: all 0.2s ease !important;
}

.menu_button:hover {
  background-color: rgba(137, 54, 25, 0.1) !important;
  color: #0E2110 !important;
  border-color: #893619 !important;
}

.menu_button_icon i { font-size: calc(var(--icon-size) * 0.8); }

#delete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG,
.red_button {
  background-color: #893619 !important;
  color: white !important;
  border: none !important;
}

#delete_button:hover,
#dialogue_del_mes_ok:hover,
.red_button:hover {
  background-color: rgba(137, 54, 25, 0.8) !important;
}

#openai_api-presets .title_restorable.standoutHeader .flex-container.gap3px { align-items: center; }
#openai_api-presets .title_restorable.standoutHeader .flex-container.gap3px div:not(label) { margin: 5px 0; }

.mes_button,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
  filter: none !important;
}

.fa-solid:not(#load-spinner) {
  font-size: var(--icon-size);
  text-shadow: none !important;
}

/* ========== 下拉框 ========== */
select {
  background-color: var(--ui-color-sec) !important;
  color: #0E2110 !important;
  border: 1px solid rgba(14, 33, 16, 0.2) !important;
  margin: calc(var(--mainFontSize) * 0.3) 0 !important;
}

select:focus {
  border: 1px solid #893619 !important;
  box-shadow: 0 0 5px rgba(137, 54, 25, 0.15) !important;
  outline: none !important;
}

select option {
  background-color: var(--ui-color-main) !important;
  color: #0E2110 !important;
}

select option:not(:checked) { color: var(--text-color-sec); }

select option:checked {
  color: var(--ui-color-sec);
  background-color: var(--text-color-main) !important;
}

.ui-widget-content .ui-state-active { color: var(--theme-color-1) !important; }

/* ========== 勾选框 ========== */
input[type="checkbox"] {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  outline: none;
  background-color: var(--ui-color-main);
  filter: none;
  box-shadow: 0 0 0 1px var(--text-color-sec);
  transform: translateY(0);
  margin-left: 1px;
}

input[type="checkbox"]::before { box-shadow: inset 1em 1em var(--theme-color-1); }
input[type="checkbox"].del_checkbox { margin-right: 0; }

/* ========== 滑动条 ========== */
input[type="range"] {
  box-shadow: none;
  background-color: var(--ui-color-sec) !important;
}

input[type="range"]:hover {
  background-color: color-mix(in srgb, var(--ui-color-sec) 70%, black 30%) !important;
}

input[type="range"]::-webkit-slider-thumb {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theme-color-1) 50%, transparent);
  background-color: var(--theme-color-1);
  width: 10px;
  height: 10px;
}

.neo-range-slider { box-shadow: inset 0 0 0 3px rgba(0, 0, 0, 0.2) !important; }

/* ========== 盒子/面板（核心：加 !important 确保覆盖ST默认暗色） ========== */
#left-nav-panel,
#right-nav-panel,
#character_popup,
#dialogue_popup,
.draggable,
#select_chat_popup,
.popup:not(.transparent_dialogue_popup),
.popup-content,   /* <--- 新增：穿透弹窗内部容器 */
dialog,           /* <--- 新增：覆盖原生弹窗标签 */
.drawer-content {
  padding: var(--spacing-long);
  background-color: var(--ui-color-main) !important;
  border-radius: var(--box-border-radius);
  border: none;
}

#dialogue_popup_text { padding: 0 var(--spacing-long) 0 0; }

#left-nav-panel,
#right-nav-panel {
  top: var(--top-distance);
  height: 100dvh !important;
  max-height: calc(100dvh - var(--top-distance) - var(--bottom-distance) - 1px);
}

@media screen and (max-width: 1000px) {
  #left-nav-panel,
  #right-nav-panel,
  .drawer-content {
    margin-top: var(--top-distance);
  }
  #left-nav-panel,
  #right-nav-panel {
    height: calc(100dvh - 45px) !important;
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
  }
}

/* 背景图库面板显式覆盖 */
#Backgrounds.drawer-content,
#Backgrounds.drawer-content.openDrawer.bg-drawer-layout {
  background-color: rgba(248, 245, 238, 0.92) !important;
}

/* ========== 首页最近聊天列表 ========== */
.select_chat_block,
#select_chat_popup .character_select,
#select_chat_popup .select_chat_block {
  background-color: rgba(248, 245, 238, 0.92) !important;
  border: 1px solid rgba(137, 54, 25, 0.15) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05) !important;
  border-radius: var(--border-radius-small);
}

.select_chat_block:hover,
#select_chat_popup .character_select:hover {
  background-color: rgba(248, 245, 238, 1) !important;
  border-color: #B8D87F !important;
}

/* ========== 列表 & 卡片 ========== */
.list-group,
.options-content,
.character_select,
.bogus_folder_select,
.bg_example,
.world_entry,
#completion_prompt_manager_list li {
  border: 1px solid rgba(137, 54, 25, 0.15) !important;
  border-radius: var(--border-radius-small);
  background-color: var(--ui-color-main) !important;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05) !important;
}

.character_select:hover,
.bg_example:hover,
#completion_prompt_manager_list li:hover {
  border-color: #B8D87F !important;
  background-color: rgba(248, 245, 238, 1) !important;
}

/* 批量选中模式：酒酿棕描边 + 背景厢深 + 左上勾选角标
   覆盖多种可能的选中类名：.selected / .selected_for_export / .bulk_selected /
   以及包含勾选 checkbox 的卡片 */
.character_select.selected,
.character_select.selected_for_export,
.character_select.bulk_selected,
.character_select:has(.bulk_select_checkbox:checked),
.character_select:has(input[type="checkbox"]:checked) {
  border: 1.5px solid rgba(184, 216, 127, 0.85) !important;
  background-color: rgba(184, 216, 127, 0.15) !important;
  box-shadow: 0 0 0 2px rgba(184, 216, 127, 0.18) !important;
  position: relative;
}

.character_select.selected::after,
.character_select.selected_for_export::after,
.character_select.bulk_selected::after,
.character_select:has(.bulk_select_checkbox:checked)::after,
.character_select:has(input[type="checkbox"]:checked)::after {
  content: "✓";
  position: absolute;
  top: 4px;
  left: 6px;
  color: rgba(137, 54, 25, 0.65);
  font-size: 18px;
  font-weight: 400;
  line-height: 1;
  z-index: 10;
  pointer-events: none;
}

#options {
  background-color: transparent !important;
  padding: 0;
}

/* ========== 世界书 Select2 下拉框 ========== */
.select2-dropdown {
  background-color: rgba(248, 245, 238, 0.95) !important;
  border: 1px solid rgba(137, 54, 25, 0.15) !important;
  border-radius: var(--border-radius-small) !important;
  color: #0E2110 !important;
}

.select2-container--default .select2-results__option {
  color: #0E2110 !important;
  background-color: transparent !important;
}

.select2-container--default .select2-results__option--highlighted[aria-selected] {
  background-color: rgba(137, 54, 25, 0.1) !important;
  color: #0E2110 !important;
}

.select2-search__field {
  background-color: var(--ui-color-sec) !important;
  color: #0E2110 !important;
  border: 1px solid rgba(14, 33, 16, 0.2) !important;
}

/* ========== 图标 ========== */
.fa-fw:not(#qr--modal-icon) { width: auto; }

#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: var(--icon-size);
}

/* ========== 头像 ========== */
.avatar img,
body.big-avatars .avatar img {
  box-shadow: none;
  border: none;
}

/* ========== 代码块 ========== */
code { margin: 0; border: none; background-color: var(--code-color); }
body[data-stscript-style] .hljs.language-stscript,
.hljs { background: var(--code-color); }
.custom-mermaid { background-color: var(--code-color); }
.standoutHeader.inline-drawer-header { padding: 5px 0; }

/* ========== 顶栏 ========== */
body.no-blur #top-bar,
#top-bar {
  border-radius: var(--border-radius-small) var(--border-radius-small) 0 0;
  box-shadow: none !important;
  background-color: transparent !important;
  border: none !important;
}

body.waifuMode #top-bar { border: none; }

#top-settings-holder {
  top: var(--top-distance);
  box-shadow: none !important;
  border: none !important;
  /* 米白半透 + 右上釉面光；不用 backdrop-filter（会损坏 fixed 后代定位） */
  background-color: rgba(248, 245, 238, 0.92) !important;
  background-image: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.4) 0%,
    rgba(255, 255, 255, 0) 30%
  ) !important;
  /* 暖色边框 + 底部极淡实线（与图标虚线描边区分） */
  border: 1px solid rgba(137, 54, 25, 0.12) !important;
  border-top: none !important;
  border-bottom: 1px solid rgba(137, 54, 25, 0.18) !important;
  border-radius: var(--border-radius-small) var(--border-radius-small) 0 0 !important;
  gap: 0 !important;
  align-items: stretch !important;
  padding: 1px 0 0 0 !important;
}

/* drawer 不再有独立背景，融入整块 */
#top-settings-holder > .drawer {
  min-width: calc(var(--apple-top-icon-size) + 14px) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  /* 不能加 position: relative：会损坏 .drawer-content 展开菜单的定位上下文 */
  transition: background-color 0.2s ease;
}

/* hover 不再用色块，改用图标层光晕（见下方 .drawer-icon:hover） */

/* active 不再用色块，改用图标层光晕 + 底部指示条 */

/* active 标识完全交给呼吸动画，不再用底部横线 */

/* active drawer-icon filter 已合并到上方统一规则 */







.drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
}

@supports (-webkit-touch-callout: none) {
  .drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
    max-width: 100dvw;
    top: var(--topBarBlockSize);
  }
}

@supports (-webkit-touch-callout: none) {
  @media screen and (min-width: 1000px) {
    #character_popup,
    #world_popup,
    .drawer-content { margin-top: 0px; }
    #top-settings-holder .drawer .drawer-content {
      right: 0;
      left: 0;
      width: var(--sheldWidth);
    }
    #left-nav-panel,
    #right-nav-panel {
      margin: 0 auto;
      top: calc(var(--topBarBlockSize) + var(--top-distance));
      max-height: calc(100dvh - var(--topBarBlockSize) - var(--bottomFormBlockSize));
      border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
      border-bottom: 1px solid var(--top-bar-underline-color);
    }
  }
}

.drawer-icon {
  opacity: 0.3;
  font-size: calc(var(--icon-size) * 1.1);
  text-shadow: none !important;
}

.drawer-icon:hover,
.drawer-icon.openIcon {
  opacity: 1;
  background: var(--gradient-main);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.drawer-content {
  box-shadow: 0 2px 0 var(--top-bar-underline-color);
  border-radius: 0 0 var(--border-radius-small) var(--border-radius-small);
}

.drawer-content h4 { font-weight: 600; }
#AdvancedFormatting h3.flex-container { flex-wrap: nowrap; }

#user-settings-block-content,
#AdvancedFormatting .flex-container.spaceEvenly { gap: 10px; }

.reverse_proxy_warning {
  border: 1px solid var(--ui-color-sec) !important;
  background-color: transparent !important;
}

/* ========== 聊天界面 ========== */
#sheld {
  top: calc(var(--topBarBlockSize) + var(--top-distance));
  height: calc(100dvh - var(--topBarBlockSize) - var(--top-distance) - 1px);
}

#chat {
  overflow-y: scroll;
  align-items: center;
  max-height: calc(100dvh - var(--topBarBlockSize) - 20px) !important;
  padding: calc(var(--scroll-width) + 4px) 0 var(--scroll-width) var(--scroll-width);
  border-radius: 0 0 var(--box-border-radius) var(--box-border-radius);
  /* 透明：聊天区本身不贴背景图。消息框贴 ibb 图（平铺），间隔区透出 ST 背景图库的 #bg1 */
  background: transparent !important;
}

@supports (-webkit-touch-callout: none) {
  #chat { padding-right: var(--scroll-width); }
}

/* 文字层透明，让 .mes 框背景透出 */
#chat .mes_block,
#chat .mes_text {
  background-color: transparent !important;
  background-image: none !important;
}

.mesAvatarWrapper {
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.mesAvatarWrapper .avatar { margin: calc(var(--mainFontSize)) 0 calc(var(--mainFontSize) * 0.4) 0; width: 80px !important; height: 80px !important; }
.mesAvatarWrapper .avatar img { width: 80px !important; height: 80px !important; object-fit: cover; }

/* 元数据三联胶囊：右上米白胶囊，酒酿棕纹，衡体字 */
/* 元数据三联胶囊：放大到 12px / padding 3px 12px；AI 右上 / user 左上 */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: inline-flex !important;
  align-items: center;
  position: absolute;
  padding: 4px 14px !important;
  background: rgba(248, 245, 238, 0.88);
  border: 1px solid rgba(137, 54, 25, 0.22);
  border-radius: 6px;
  font-family: 'Cormorant Garamond', 'EB Garamond', 'Garamond', 'Georgia', serif;
  font-size: 13px !important;
  line-height: 1.4;
  letter-spacing: 0.02em;
  color: rgba(137, 54, 25, 0.78) !important;
  text-shadow: none !important;
  z-index: 5;
}

/* AI 消息右上：三层纵排 */
#chat div[is_user="false"] .mesIDDisplay { top: 14px; right: 14px; left: auto; }
#chat div[is_user="false"] .mes_timer { top: 46px; right: 14px; left: auto; }
#chat div[is_user="false"] .tokenCounterDisplay { top: 78px; right: 14px; left: auto; }

/* User 消息左上：隐藏 timer（用户没有思考时长），两层 */
