}

/* 消息底部主按钮区：100% 宽底门胶囊条 absolute 居中时不被裁切 */
.mes_block .mes_buttons {
  position: absolute !important;
  bottom: 18px;
  left: 0;
  right: 0;
  width: 100%;
  display: flex !important;
  justify-content: center;
  align-items: center;
  gap: 12px !important;
  opacity: 1 !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 3;
}

/* 3 个原生主按钮（… / 铅笔 / 旗子）统一胶囊 + SKETCH-6 釉光虚线化；小白X 不处理 */
.mes_block .mes_buttons > .mes_button {
  position: relative;
  z-index: 6;
  box-sizing: border-box !important;
  width: 30px !important;
  height: 30px !important;
  border-radius: 50% !important;
  background: rgba(248, 245, 238, 0.85) !important;
  color: #893619 !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  font-size: 13px !important;
  padding: 0 !important;
  margin: 0 !important;
  /* 方案 A：虚线用 border 实现，close 实线 border，hover/open 切换为 dashed 加深 */
  border: 1.5px solid rgba(137, 54, 25, 0.18) !important;
  opacity: 1 !important;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), background 0.3s ease, border-color 0.3s ease, border-style 0.001s linear;
}

/* SKETCH-6 釉光扫动层；inset -3 避免与 outline 虚线撞色 */
.mes_block .mes_buttons > .mes_button::after {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: linear-gradient(
    135deg,
    transparent 0%,
    transparent 35%,
    rgba(255, 248, 231, 0.85) 50%,
    transparent 65%,
    transparent 100%
  );
  background-size: 250% 250%;
  background-position: 100% 100%;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask-composite: exclude;
  padding: 1.5px;
  opacity: 0;
  transition: opacity 0.32s ease;
  z-index: -1;
  pointer-events: none;
}

/* hover：虚线蜡金 + 釉光流转 + 轻放大 */
.mes_block .mes_buttons > .mes_button:hover {
  transform: scale(1.04);
  background: rgba(248, 245, 238, 0.95) !important;
  border-style: dashed !important;
  border-color: rgba(137, 54, 25, 0.7) !important;
}
.mes_block .mes_buttons > .mes_button:hover::after {
  opacity: 1;
  animation: apple-glaze-sweep 1.8s ease-in-out infinite;
}

/* active（点开状态）：虚线蜡金实 + 釉光慢扫 */
.mes_block .mes_buttons > .mes_button:active {
  border-style: dashed !important;
  border-color: rgba(137, 54, 25, 0.95) !important;
}
.mes_block .mes_buttons > .mes_button:active::after {
  opacity: 1;
  animation: apple-glaze-sweep 3s ease-in-out infinite;
}

/* ===== 二级菜单统一颜色（无 SKETCH-6 动效、不强调交互） ===== */

