/* === 小白X 重做：套 SKETCH-6 圆胶囊 + 内部×字符 + 子菜单居中覆盖 === */

/* 小白X 主按钮：与原生三主按钮同款胶囊 + SKETCH-6 釉光虚线 */
.mes_block .mes_buttons > .xiaobaix-collapse-btn,
.mes_block .mes_buttons > .mes_btn.xiaobaix-collapse-btn {
  position: relative !important;
  z-index: 6 !important;
  box-sizing: border-box !important;
  width: 30px !important;
  height: 30px !important;
  min-width: 30px !important;
  max-width: 30px !important;
  flex: 0 0 30px !important;
  border-radius: 50% !important;
  background: rgba(248, 245, 238, 0.85) !important;
  /* 方案 A：虚线用 border 实现 */
  border: 1.5px solid rgba(137, 54, 25, 0.18) !important;
  color: #893619 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-shadow: none !important;
  filter: none !important;
  cursor: pointer;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), background 0.3s ease, border-color 0.3s ease, border-style 0.001s linear;
}

/* 隐藏原生 4个X字符堆，用按钮自身 ::before 填× */
.xiaobaix-collapse-btn .xiaobaix-xstack {
  display: none !important;
}
.mes_block .mes_buttons > .xiaobaix-collapse-btn::before {
  content: "\d7";
  font-family: 'Cormorant Garamond', 'EB Garamond', 'Georgia', serif;
  font-size: 18px;
