  color: #893619;
}

/* hover 状态：虚线蜡金 + 轻放大 */
.mes_block .mes_buttons > .xiaobaix-collapse-btn:hover,
.mes_block .mes_buttons > .mes_btn.xiaobaix-collapse-btn:hover {
  transform: scale(1.04);
  background: rgba(248, 245, 238, 0.95) !important;
  border-style: dashed !important;
  border-color: rgba(137, 54, 25, 0.7) !important;
}

/* open 状态：主按钮形状/位置/× 字符完全保持不变，仅 outline 实色标识展开；
   禁用 transition 让 outline 切换无动画，根除闪烁 */
.mes_block .mes_buttons > .xiaobaix-collapse-btn.open,
.mes_block .mes_buttons > .mes_btn.xiaobaix-collapse-btn.open {
  border-style: dashed !important;
  border-color: rgba(137, 54, 25, 0.95) !important;
  transition: none !important;
}
/* open 状态 hover：禁用 transform scale 防止子菜单抖动；保留原视觉 */
.mes_block .mes_buttons > .xiaobaix-collapse-btn.open:hover,
.mes_block .mes_buttons > .mes_btn.xiaobaix-collapse-btn.open:hover {
