}

/* 子菜单：贴在主按钮左边 6px 竖直居中；close 时交给扩展默认（right: 38px）；
   border 在嵌套 stacking context 中视觉不可见，用 box-shadow inset 兜底描边 */
.mes_block .mes_buttons .xiaobaix-collapse-btn.open .xiaobaix-sub-container {
