  min-height: var(--apple-top-icon-size) !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  text-shadow: none !important;
  opacity: 1 !important;
  background-image: var(--apple-icon-url) !important;
  background-repeat: no-repeat !important;
  background-position: center center !important;
  background-size: contain !important;
  /* 方向 E：原色满血，只用转换微动 */
  opacity: 1 !important;
  filter: none !important;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}

/* 原“隐藏 .drawer-icon::before”规则已删除，SKETCH-6 需要它画虚线描边 */

/* SKETCH-6 釉光虚线 - 顶栏；整体下挪 2px 避免顶边被遮 */
#top-settings-holder .drawer-icon {
  position: relative;
  z-index: 1;
  transform: translateY(2px);
}

#top-settings-holder .drawer-icon::before {
  content: "";
  position: absolute;
  /* inset: -2px 避免顶边被顶栏容器顶部遮挡 */
  inset: -2px;
  border: 1.5px dashed rgba(212, 165, 116, 0);
  border-radius: 6px;
  transition: border-color 0.32s ease;
  pointer-events: none;
}

#top-settings-holder .drawer-icon::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 6px;
  background: linear-gradient(
    135deg,
    transparent 0%,
    transparent 35%,
    rgba(255, 248, 231, 0.85) 50%,
    transparent 65%,
    transparent 100%
  );
  background-size: 250% 250%;
  background-position: 100% 100%;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
          mask-composite: exclude;
  padding: 1.5px;
  opacity: 0;
  transition: opacity 0.32s ease;
  z-index: -1;
  pointer-events: none;
}

#top-settings-holder .drawer-icon:hover {
  /* 抵消原 .drawer-icon:hover 的 background-clip:text，防止 PNG 图标消失 */
  background-image: var(--apple-icon-url) !important;
  -webkit-background-clip: initial !important;
          background-clip: initial !important;
  color: transparent !important;
  transform: translateY(2px) scale(1.04);
}
#top-settings-holder .drawer-icon:hover::before {
  border-color: rgba(212, 165, 116, 0.7);
}
#top-settings-holder .drawer-icon:hover::after {
  opacity: 1;
  animation: apple-glaze-sweep 1.8s ease-in-out infinite;
}

/* active：描边加实 + 釉光慢扫 */
#top-settings-holder > .drawer:has(.openDrawer) .drawer-icon,
#top-settings-holder .drawer-icon.openIcon {
  /* 抵消原 .drawer-icon.openIcon 的 background-clip:text，防止 PNG 图标消失 */
  background-image: var(--apple-icon-url) !important;
  -webkit-background-clip: initial !important;
          background-clip: initial !important;
  color: transparent !important;
  transform: translateY(2px) scale(1.04);
}
#top-settings-holder > .drawer:has(.openDrawer) .drawer-icon::before,
#top-settings-holder .drawer-icon.openIcon::before {
  border-color: rgba(212, 165, 116, 1);
}
#top-settings-holder > .drawer:has(.openDrawer) .drawer-icon::after,
#top-settings-holder .drawer-icon.openIcon::after {
  opacity: 1;
  animation: apple-glaze-sweep 3s ease-in-out infinite;
}

/* SKETCH-6 釉光扫过 keyframes：合作描边虚线实现玻璃质感 */
@keyframes apple-glaze-sweep {
  0%   { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

