  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block !important;
  animation: apple-poem-fade-in 0.8s ease 0.2s both;
}

@keyframes apple-poem-fade-in {
  from {
    opacity: 0;
    transform: translateY(-50%) translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(-50%) translateX(0);
  }
}

/* 聚焦或有内容时淑出诗 */
#send_form:has(#send_textarea:focus)::after,
#send_form:has(#send_textarea:not(:placeholder-shown))::after {
  animation: none !important;
  opacity: 0 !important;
}

/* 隐藏原 placeholder 文字 */
#send_textarea::placeholder {
  color: transparent !important;
}


/* ========== 首页 welcomePanel：透明 + 虚线边 ========== */
.welcomePanel,
.welcome-panel,
#version_display,
#welcomePanel {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  -webkit-backdrop-filter: none !important;
          backdrop-filter: none !important;
  border: 1.5px dashed rgba(137, 54, 25, 0.45) !important;
  border-radius: 12px !important;
  box-shadow: none !important;
}

/* ========== Markdown 渲染样式（消息区） ========== */

/* 清除发光描边对代码/标记类元素的糊化影响 */
#chat .mes_text code,
#chat .mes_text pre,
#chat .mes_text pre *,
#chat .mes_text kbd,
#chat .mes_text mark,
#chat .mes_text blockquote,
#chat .mes_text blockquote * {
  text-shadow: none !important;
}

/* 行内代码：暖米底 + 酒酿色字 + 极淡描边 */
#chat .mes_text code {
  background-color: rgba(238, 233, 222, 0.85) !important;
  color: #893619 !important;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid rgba(137, 54, 25, 0.18);
  font-family: 'JetBrains Mono', 'Fira Code', Consolas, monospace;
  font-size: 0.92em;
}

/* 代码块 */
#chat .mes_text pre {
  background: rgba(238, 233, 222, 0.85) !important;
  border: 1px dashed rgba(137, 54, 25, 0.32);
  border-radius: 8px;
  padding: 10px 14px;
  margin: 10px 0;
  overflow-x: auto;
}
#chat .mes_text pre code {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  color: #0E2110 !important;
  font-size: 0.9em;
}

/* 引用块：虚线包裹 + 双弯引号装饰 + 嵌套柔化 */
#chat .mes_text blockquote {
  position: relative;
  margin: 12px 0;
  padding: 10px 18px 10px 26px;
  border: 1.5px dashed rgba(137, 54, 25, 0.42);
  border-radius: 8px;
  background: rgba(248, 245, 238, 0.55);
  color: #5a3a1c !important;
  font-style: italic;
}
#chat .mes_text blockquote::before {
  content: '❝';
  position: absolute;
  top: 2px;
  left: 8px;
  color: rgba(137, 54, 25, 0.55);
  font-size: 1.4em;
  line-height: 1;
  font-family: 'Cormorant Garamond', 'Georgia', serif;
  font-style: normal;
}
#chat .mes_text blockquote::after {
  content: '❞';
  position: absolute;
  bottom: -2px;
  right: 10px;
  color: rgba(137, 54, 25, 0.32);
  font-size: 1.1em;
  line-height: 1;
  font-family: 'Cormorant Garamond', 'Georgia', serif;
  font-style: normal;
}
#chat .mes_text blockquote p:last-child { margin-bottom: 0; }
#chat .mes_text blockquote blockquote {
  margin: 8px 0 4px 0;
  border-color: rgba(137, 54, 25, 0.28);
  background: rgba(248, 245, 238, 0.35);
}

/* HTML 高亮 mark：做旧米黄底 + 焦糖棕字 */
#chat .mes_text mark {
  background-color: rgba(232, 200, 138, 0.45) !important;
  color: #6b3a1a !important;
  padding: 1px 4px;
  border-radius: 3px;
}

/* details/summary：虚线框 + ❯ 旋转箭头 + open 转苹果叶绿 */
#chat .mes_text details {
  border: 1.5px dashed rgba(137, 54, 25, 0.35);
  border-radius: 8px;
  padding: 6px 12px;
  margin: 10px 0;
  background: rgba(248, 245, 238, 0.5);
  transition: border-color 0.25s ease, background 0.25s ease;
}
#chat .mes_text details[open] {
  border-color: rgba(122, 156, 69, 0.55);
  background: rgba(248, 245, 238, 0.7);
}
#chat .mes_text details > summary {
  list-style: none;
  cursor: pointer;
  color: #893619;
  font-weight: 600;
  padding: 4px 0 4px 22px;
  position: relative;
  user-select: none;
  transition: color 0.2s ease;
}
#chat .mes_text details > summary::-webkit-details-marker { display: none; }
#chat .mes_text details > summary::marker { content: ''; }
#chat .mes_text details > summary::before {
  content: '❯';
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%) rotate(0deg);
  color: rgba(137, 54, 25, 0.7);
  font-size: 0.92em;
  font-weight: 700;
  transition: transform 0.32s cubic-bezier(0.34, 1.56, 0.64, 1), color 0.25s ease;
}
#chat .mes_text details[open] > summary::before {
  transform: translateY(-50%) rotate(90deg);
  color: rgba(122, 156, 69, 0.95);
}
#chat .mes_text details > summary:hover { color: #6b3a1a; }
#chat .mes_text details > summary:hover::before { color: rgba(137, 54, 25, 1); }

/* 链接：虚线下划线 + 悬停转苹果红 */
#chat .mes_text a {
  color: #893619 !important;
  text-decoration: underline;
  text-decoration-style: dashed;
  text-decoration-color: rgba(137, 54, 25, 0.4);
  text-underline-offset: 3px;
  transition: color 0.2s ease, text-decoration-color 0.2s ease;
}
#chat .mes_text a:hover {
  color: #B26B5F !important;
  text-decoration-color: rgba(178, 107, 95, 0.85);
}

/* 删除线：弱化 */
#chat .mes_text del,
#chat .mes_text s,
#chat .mes_text strike {
  color: rgba(14, 33, 16, 0.55) !important;
  text-decoration-color: rgba(137, 54, 25, 0.55);
}

/* 下划线 u：苹果红低饱和 */
#chat .mes_text u {
  text-decoration-color: rgba(178, 107, 95, 0.8);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 2px;
}

/* 上下标 */
#chat .mes_text sub,
#chat .mes_text sup {
  color: rgba(137, 54, 25, 0.85) !important;
  font-size: 0.78em;
}

/* 水平分割线 */
#chat .mes_text hr {
  border: none;
  border-top: 1.5px dashed rgba(137, 54, 25, 0.4);
  margin: 14px 0;
}

/* kbd 按键 */
#chat .mes_text kbd {
  display: inline-block;
  padding: 1px 7px;
  background: rgba(248, 245, 238, 0.95);
  border: 1px solid rgba(137, 54, 25, 0.35);
  border-bottom-width: 2px;
  border-radius: 4px;
  color: #893619 !important;
  font-family: 'JetBrains Mono', Consolas, monospace;
  font-size: 0.85em;
  box-shadow: 0 1px 0 rgba(137, 54, 25, 0.15);
}

/* 表格：虚线描边 + 表头浅酒酿色 + 偶数行做旧米白 */
#chat .mes_text table {
  border-collapse: collapse;
  margin: 10px 0;
  border: 1px dashed rgba(137, 54, 25, 0.4);
  background: rgba(248, 245, 238, 0.5);
}
#chat .mes_text th,
#chat .mes_text td {
  border: 1px dashed rgba(137, 54, 25, 0.25);
  padding: 6px 10px;
  color: #0E2110 !important;
}
#chat .mes_text th {
  background: rgba(137, 54, 25, 0.1);
  color: #893619 !important;
  font-weight: 600;
  letter-spacing: 0.02em;
}
#chat .mes_text tr:nth-child(even) td { background: rgba(238, 233, 222, 0.4); }

/* 消息内层级标题 */
#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4,
#chat .mes_text h5,
#chat .mes_text h6 {
  color: #893619 !important;
  font-weight: 600;
  border-bottom: 1px dashed rgba(137, 54, 25, 0.25);
  padding-bottom: 4px;
  margin: 14px 0 8px 0;
}
#chat .mes_text h1 { font-size: 1.5em; }
#chat .mes_text h2 { font-size: 1.32em; }
#chat .mes_text h3 { font-size: 1.18em; }
#chat .mes_text h4 { font-size: 1.08em; border-bottom-style: dotted; }
#chat .mes_text h5 { font-size: 1em; border-bottom: none; }
#chat .mes_text h6 { font-size: 0.95em; border-bottom: none; opacity: 0.85; }
